vector<int> v = {3, 1, 4, 1, 5};
int k = 2;
multiset<int> s(v.begin(), v.begin()+k);
int ans = *s.rbegin();
for(int i = k; i < v.size(); i++) { s.erase(s.find(v[i-k]));
    s.insert(v[i]);
    ans = max(ans, *s.rbegin());
}
cout << ans;

In Python, what is the output?
def kadane(arr): max_so_far = max_ending_here = arr[0];
for x in arr[1:]: max_ending_here = max(x, max_ending_here + x);
max_so_far = max(max_so_far, max_ending_here);
return max_so_far;
print(kadane([-2, 1, -3, 4, -1, 2, 1]))

In C, what is the output of this KMP preprocessing?
void computeLPS(char *pat, int m, int *lps) { int len = 0, i = 1;
    lps[0] = 0;
    while(i < m) { if(pat[i] == pat[len]) { len++;
            lps[i++] = len;
        }
        else if(len > 0) len = lps[len-1];
        else lps[i++] = 0;
}}
int lps[6];
computeLPS("AABAAC", 6, lps);
printf("%d", lps[5]);

In Python, what is the output?
def edit_distance(s1, s2): m, n = len(s1), len(s2);
dp = [[0]*(n+1) for _ in range(m+1)];
for i in range(m+1): dp[i][0] = i;
for j in range(n+1): dp[0][j] = j;
for i in range(1, m+1): for j in range(1, n+1): if s1[i-1] == s2[j-1]: dp[i][j] = dp[i-1][j-1];
else: dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1;
return dp[m][n];
print(edit_distance("cat", "cut"))

